-- public.flower_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.flower_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare d action_def; p player; tx int; ty int; v_season text;
begin
  select * into d from action_def where id = p_action;
  select * into p from player where world_id = p_world and uid = p_uid;
  if p_target->>'kind' is distinct from 'tile' then return 'Choose the ground.'; end if;
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  if not in_bounds(p_world, tx, ty) then return 'There is nothing there.'; end if;
  if not in_reach(p.x, p.y, p_target, false, d.range) then return 'You are too far away from that.'; end if;
  if land_tile(p_world, tx, ty) <> tile_id('Grass') then return 'Wildflowers grow on grass only.'; end if;
  if exists (select 1 from building_tile b where b.world_id = p_world and b.x = tx and b.y = ty) then
    return 'Not inside a building.';
  end if;
  v_season := season_at();
  if not exists (select 1 from flower_season s where s.season = v_season and s.drift is not null) then
    return 'No flowers in ' || v_season || ': wildflowers bloom in ' || flower_seasons_said() || '.';
  end if;
  -- Until the season a year begins with.
  if (land_data(p_world, tx, ty) & flowers_picked()::int) <> 0 then
    return 'Already picked: flowers again in spring.';
  end if;
  if flowers_on(p_world, tx, ty) = 0 then return 'No flowers here.'; end if;
  return null;
end $function$
